(()=>{'use strict';const form=document.getElementById('booking-form'),steps=[...document.querySelectorAll('.step')],next=document.getElementById('next'),back=document.getElementById('back'),submit=document.getElementById('submit'),error=document.getElementById('form-error');let step=0;const labels={photography:'Photography session',restaurant:'Restaurant photography',brand:'Brand content',consultation:'Strategy consultation'};function service(){return new FormData(form).get('service')}function fields(){document.querySelectorAll('[data-for]').forEach(el=>{const active=el.dataset.for.split(',').includes(service());el.hidden=!active;el.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=!active)});const text={restaurant:'What should this shoot achieve for your restaurant?',brand:'What is your brand’s goal and where will the content be used?',consultation:'What would you like help with?',photography:'What would you like this session to capture?'};document.getElementById('objective-label').textContent=text[service()]||'What would you like to achieve?';form.elements.objectives.placeholder=service()==='consultation'?'Tell us about your priorities, challenges and what you want to achieve.':'Tell us what matters to you and how you plan to use the images.'}function review(){const values=new FormData(form),dl=document.getElementById('review');dl.replaceChildren();const rows=[['Service',labels[values.get('service')]],['Preferred date & time',values.get('date')+' · '+values.get('time')+' ('+values.get('timezone')+')'],['Name',values.get('name')],['Email',values.get('email')],['Phone',values.get('phone')],['Location',values.get('location')],['Session type',values.get('session_type')],['Business',values.get('business_name')],['Meeting',values.get('meeting_mode')],['Photographs',values.get('photo_quantity')==='advice'?'I would like your recommendation':values.get('photo_quantity')],['Objectives',values.get('objectives')],['Notes',values.get('notes')]];rows.filter(x=>x[1]).forEach(([label,value])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd)})}function show(n){step=n;fields();steps.forEach((el,i)=>el.hidden=i!==n);back.hidden=n===0;next.hidden=n===3;submit.hidden=n!==3;document.getElementById('step-label').textContent='STEP 0'+(n+1)+' / 04';document.querySelectorAll('#progress li').forEach((el,i)=>i===n?el.setAttribute('aria-current','step'):el.removeAttribute('aria-current'));error.textContent='';if(n===3)review();steps[n].querySelector('h2').focus()}function valid(){if(step===0&&!service()){error.textContent='Please choose a service.';form.querySelector('[name="service"]').focus();return false}for(const field of steps[step].querySelectorAll('input,select,textarea')){if(!field.disabled&&!field.checkValidity()){field.reportValidity();return false}}if(step===1){const d=new FormData(form),parts=new Intl.DateTimeFormat('en-CA',{timeZone:d.get('timezone'),year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),obj=Object.fromEntries(parts.map(x=>[x.type,x.value])),today=obj.year+'-'+obj.month+'-'+obj.day;if(!d.get('date')){error.textContent='Please choose a preferred date.';document.querySelector('#calendar-days button:not(:disabled)')?.focus();return false}if(d.get('date')<today){error.textContent='Please choose today or a future date.';document.querySelector('#calendar-days button:not(:disabled)')?.focus();return false}}return true}next.onclick=()=>{if(valid())show(step+1)};back.onclick=()=>show(step-1);form.addEventListener('submit',e=>{e.preventDefault();error.textContent='This preview does not send requests yet.'});form.addEventListener('change',fields);fields();})();

(()=>{'use strict';const form=document.getElementById('booking-form'),days=document.getElementById('calendar-days'),monthLabel=document.getElementById('calendar-month'),prev=document.getElementById('month-prev'),next=document.getElementById('month-next'),choice=document.getElementById('calendar-choice');function today(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:form.elements.timezone.value,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day}const iso=d=>d.toISOString().slice(0,10);let view=new Date(today()+'T12:00:00Z');view.setUTCDate(1);function render(focusDate){const minimum=today(),year=view.getUTCFullYear(),month=view.getUTCMonth(),selected=form.elements.date.value;monthLabel.textContent=new Intl.DateTimeFormat('en-AU',{month:'long',year:'numeric',timeZone:'UTC'}).format(view);days.replaceChildren();const offset=(new Date(Date.UTC(year,month,1)).getUTCDay()+6)%7;for(let i=0;i<offset;i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');days.append(blank)}const count=new Date(Date.UTC(year,month+1,0)).getUTCDate();for(let i=1;i<=count;i++){const d=new Date(Date.UTC(year,month,i,12)),value=iso(d),b=document.createElement('button');b.type='button';b.textContent=i;b.dataset.date=value;b.disabled=value<minimum;b.setAttribute('aria-label',new Intl.DateTimeFormat('en-AU',{dateStyle:'full',timeZone:'UTC'}).format(d));b.setAttribute('aria-pressed',String(value===selected));if(value===minimum)b.setAttribute('aria-current','date');b.addEventListener('click',()=>{form.elements.date.value=value;choice.textContent=new Intl.DateTimeFormat('en-AU',{dateStyle:'full',timeZone:'UTC'}).format(d)+' · preferred date';render(value)});days.append(b)}prev.disabled=iso(view).slice(0,7)<=minimum.slice(0,7);const buttons=[...days.querySelectorAll('button:not(:disabled)')];const active=buttons.find(x=>x.dataset.date===(focusDate||selected))||buttons.find(x=>x.dataset.date===minimum)||buttons[0];buttons.forEach(b=>b.tabIndex=b===active?0:-1);if(focusDate)active?.focus()}function shift(delta){view.setUTCMonth(view.getUTCMonth()+delta);render()}prev.addEventListener('click',()=>shift(-1));next.addEventListener('click',()=>shift(1));days.addEventListener('keydown',e=>{const b=e.target.closest('button[data-date]');if(!b)return;const d=new Date(b.dataset.date+'T12:00:00Z');let change=({ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7})[e.key];if(e.key==='Home')change=-((d.getUTCDay()+6)%7);if(e.key==='End')change=6-((d.getUTCDay()+6)%7);if(e.key==='PageUp'||e.key==='PageDown'){e.preventDefault();const originalDay=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+(e.key==='PageDown'?1:-1));d.setUTCDate(Math.min(originalDay,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));if(iso(d)<today())return;view=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1,12));render(iso(d));return}if(change===undefined)return;e.preventDefault();d.setUTCDate(d.getUTCDate()+change);if(iso(d)<today())return;view=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1,12));render(iso(d))});form.elements.timezone.addEventListener('change',()=>{if(form.elements.date.value&&form.elements.date.value<today()){form.elements.date.value='';choice.textContent='Choose a date above'}if(iso(view).slice(0,7)<today().slice(0,7))view=new Date(today().slice(0,7)+'-01T12:00:00Z');render()});function time(){form.elements.time.value=form.elements.hour.value!==''&&form.elements.minute.value!==''?form.elements.hour.value+':'+form.elements.minute.value:''}form.elements.hour.addEventListener('change',time);form.elements.minute.addEventListener('change',time);render();})();
